// Sample order data - replace with your actual trigger data
const orderData = {
  customerId: 'CUST123',
  items: [
    { tireId: 'MIC-235-55R17', qty: 4, type: 'PCR', customerType: 'RETAIL' },
    { tireId: 'BS-205-65R16', qty: 2, type: 'PCR', customerType: 'WHOLESALE' }
  ],
  services: ['mounting', 'balancing']
};

return orderData;

// Fetch tire details from your database
const tireDetails = {
  'MIC-235-55R17': {
    brand: 'Michelin',
    model: 'Primacy 4',
    size: '235/55R17',
    dotNumbers: ['DOT XYZ123456', 'DOT XYZ123457', 'DOT XYZ123458', 'DOT XYZ123459'],
    wholesalePrice: 85.00,
    retailPrice: 120.00,
    hsnCode: '4011.10'
  },
  'BS-205-65R16': {
    brand: 'Bridgestone',
    model: 'Turanza',
    size: '205/65R16',
    dotNumbers: ['DOT ABC987654', 'DOT ABC987655'],
    wholesalePrice: 72.00,
    retailPrice: 105.00,
    hsnCode: '4011.10'
  }
};

// Apply B2B pricing
const items = $input.all()[0].json.items.map(item => {
  const tire = tireDetails[item.tireId];
  const unitPrice = item.customerType === 'WHOLESALE' 
    ? tire.wholesalePrice * 1.15 // 15% markup for wholesale
    : tire.retailPrice;

  return {
    ...item,
    ...tire,
    unitPrice,
    total: unitPrice * item.qty,
    dotNumbers: tire.dotNumbers.slice(0, item.qty)
  };
});

return { items, services: $input.all()[0].json.services };

// Calculate services and totals
const servicePrices = {
  mounting: 15.00,
  balancing: 12.50,
  disposal: 5.00,
  valveStem: 4.00
};

const items = $input.all()[0].json.items;
const services = $input.all()[0].json.services.map(service => ({
  name: service,
  price: servicePrices[service],
  hsnCode: '9988', // SAC code for services
  gstRate: 18
}));

const subtotal = items.reduce((sum, item) => sum + item.total, 0) +
                 services.reduce((sum, service) => sum + service.price, 0);

const gst = items.reduce((sum, item) => sum + (item.total * 0.18), 0) +
            services.reduce((sum, service) => sum + (service.price * 0.18), 0);

const invoiceNumber = `INV-${new Date().getFullYear()}${(new Date().getMonth() + 1).toString().padStart(2, '0')}-${Math.floor(1000 + Math.random() * 9000)}`;

return {
  invoiceNumber,
  items,
  services,
  subtotal,
  gst,
  total: subtotal + gst,
  date: new Date().toISOString().split('T')[0]
};

// Generate QR codes
const QRCode = require('qrcode');

async function generateQR(text) {
  try {
    return await QRCode.toDataURL(text);
  } catch (err) {
    console.error(err);
    return '';
  }
}

const invoiceData = $input.all()[0].json;
const paymentLink = `https://yourpaymentportal.com/pay?invoice=${invoiceData.invoiceNumber}&amount=${invoiceData.total}`;
const warrantyLink = `https://yourwarrantyportal.com/register?invoice=${invoiceData.invoiceNumber}`;
const serviceLink = `https://yourserviceportal.com/history?invoice=${invoiceData.invoiceNumber}`;

const paymentQR = await generateQR(paymentLink);
const warrantyQR = await generateQR(warrantyLink);
const serviceQR = await generateQR(serviceLink);

return {
  ...invoiceData,
  qrCodes: {
    payment: paymentQR,
    warranty: warrantyQR,
    service: serviceQR
  }
};

return {
  logo: "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAA...",
  footerText: "Your Company Name | GSTIN: XXXXXXXX | Contact: info@yourcompany.com"
};
